import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg.get('resolvedVersion', pkg.get('requestedVersion','?'))
        result[name] = pkgs
    return result

b = get_pkgs(baseline)
a = get_pkgs(after)
changes = []
unchanged = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {}); ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg); av = ap.get(pkg)
        if bv != av:
            changes.append((proj, pkg, bv or '-', av or '-'))
        else:
            unchanged.append((proj, pkg, bv))
print('=== CHANGES ===')
for c in changes: print(f'  {c[0]:20s} {c[1]:40s} {c[2]:>10s} -> {c[3]}')
if not changes: print('  (none)')
print(f'\n=== UNCHANGED === ({len(unchanged)} entries)')
for u in unchanged[:5]: print(f'  {u[0]:20s} {u[1]:40s} {u[2]:>10s}')
if len(unchanged)>5: print(f'  ... and {len(unchanged)-5} more')
"

